/**
 * tests/mission_parity.js — end-to-end mission parity vs the full app.
 *
 * Runs the sandbox pipeline (build → formulate → roll-up) on the shipped
 * scenarios and pins the mission roll-up against the full application's
 * Python output (fixtures/mission_parity_python.json, generated by
 * tools/gen_mission_fixture.py):
 *   - campaign count within ±2
 *   - total waste oxide ±5%
 *   - total glass mass ±7% (glass = Σ waste_kg/WL; WL parity is pinned
 *     separately, so the residual is blend-assignment wiggle)
 *   - every campaign's glass formulation FEASIBLE (all 11 constraints)
 *
 * Run: node tests/mission_parity.js
 */
'use strict';
const fs = require('fs');
const path = require('path');
const Engine = require('../web/js/engine/engine.js');
const Glass = require('../web/js/engine/glass.js');

const dataPath = path.join(__dirname, '..', 'web', 'data', 'mission_data.json');
const DATA = JSON.parse(fs.readFileSync(dataPath, 'utf8'));
Glass.setCovariance(DATA.covariance);

const TAG = process.argv[2] || '135.120.150';
const WITH_HEELS = process.argv[3] === 'heels';
const fxName = WITH_HEELS ? 'mission_parity_python_heels.json' : 'mission_parity_python.json';
const fxPath = path.join(__dirname, 'fixtures', fxName);
const PY = fs.existsSync(fxPath) ? JSON.parse(fs.readFileSync(fxPath, 'utf8')) : null;

let passed = 0, failed = 0;
function check(name, cond, extra) {
  if (cond) passed++;
  else { failed++; console.error(`FAIL: ${name}`, extra || ''); }
}

const scen = JSON.parse(JSON.stringify(DATA.scenarios[TAG]));
scen.__wacRows = DATA.wac;

const t0 = Date.now();
const mission = Engine.buildMission(scen, { includeHeels: WITH_HEELS });
console.log(`built ${mission.campaigns.length} campaigns in ${Date.now() - t0} ms` +
            (WITH_HEELS ? ' (App-D + heels)' : ' (App-D layers only)'));

// per-campaign glass evaluation
const t1 = Date.now();
let allFeasible = true, wlSum = 0, nEval = 0;
for (const c of mission.campaigns) {
  const waste = Engine.campaignWasteVector(scen.layers, c.recipe);
  const r = Glass.formulate(waste);
  c.waste_loading = r.waste_loading;
  c.glass_kg = r.waste_loading > 0 ? c.waste_kg / r.waste_loading : 0;
  c.all_pass = r.success && r.evaluation.all_pass;
  if (!c.all_pass) allFeasible = false;
  wlSum += r.waste_loading;
  nEval++;
}
const evalMs = Date.now() - t1;
console.log(`evaluated ${nEval} campaigns in ${evalMs} ms (${(evalMs / Math.max(nEval, 1)).toFixed(0)} ms/campaign)`);

const totals = Engine.missionTotals(mission.campaigns, null, {});
console.log(`totals: waste ${(totals.total_waste_kg / 1e6).toFixed(2)} Mt oxide, ` +
            `glass ${(totals.total_glass_kg / 1e6).toFixed(2)} Mt, ` +
            `${totals.canisters.toFixed(0)} canisters, ` +
            `${totals.duration_years.toFixed(1)} y @ 5 t/d × 65%`);

// ---- structural checks ------------------------------------------------
check('produced campaigns', mission.campaigns.length >= 20,
      `got ${mission.campaigns.length}`);
check('all campaigns feasible', allFeasible,
      mission.campaigns.filter(c => !c.all_pass).slice(0, 3));
check('avg WL in sane range', totals.avg_waste_loading > 0.15 &&
      totals.avg_waste_loading < 0.50, totals.avg_waste_loading);
check('canisters in sane range', totals.canisters > 3000 && totals.canisters < 60000,
      totals.canisters);
const vols = mission.campaigns.map(c => c.volume_kL);
const KL = 3.785412;
const inBand = vols.filter(v => v >= 450 * KL - 1 && v <= 550 * KL + 1).length;
// Full-app reference @135.120.150: App-D scope packs 11 of 39 campaigns in
// the band; most campaigns run sub-floor because the ≤5-tank cap × small
// remaining layers cannot always reach the 1,703 kL band minimum.  The
// heel scope adds 71 small heel layers, so the in-band share differs —
// check the App-D scope against the reference range and both scopes for
// a plausible non-zero band occupancy.
if (WITH_HEELS) {
  check('heel scope packs a plausible band share', inBand >= 10,
        `${inBand}/${vols.length}`);
} else if (TAG === '135.120.150') {
  // Full-app reference: 39 App-D campaigns of which 11 are in-band; most
  // run sub-floor because ≤5 tanks × small remaining layers can't always
  // reach the 1,703 kL band minimum.
  check('sub-floor campaigns match full-app behavior (11 in-band @135.120.150)',
        inBand >= 8 && inBand <= 16, `${inBand}/${vols.length}`);
} else {
  // Other tags: just require a sane non-zero band occupancy (full-app
  // reference @135.105.200 App-D is 2/29 — this scenario's layers are
  // smaller, so nearly every campaign runs sub-floor).
  check('band occupancy sane for tag', inBand >= 1, `${inBand}/${vols.length}`);
}
// every layer drawn at most once (sum of fractions ≤ 1)
{
  const draw = {};
  for (const c of mission.campaigns) {
    for (const r of c.recipe) draw[r.layer] = (draw[r.layer] || 0) + r.fraction;
  }
  const over = Object.entries(draw).filter(([l, f]) => f > 1.001);
  check('no layer over-drawn', over.length === 0, over.slice(0, 3));
}
// quadrant order: no campaign mixes quadrants (in-flight carryover aside)
{
  const mixed = mission.campaigns.filter(c => {
    const quads = new Set(c.recipe.map(r => scen.layers[r.layer].quad));
    return quads.size > 1;
  });
  check('campaigns stay within one quadrant', mixed.length === 0, mixed.length);
}

// ---- parity vs full app ----------------------------------------------
if (PY && PY[TAG]) {
  const py = PY[TAG];
  check('campaign count within 25%',
        Math.abs(mission.campaigns.length - py.n_campaigns) / py.n_campaigns <= 0.25,
        `JS ${mission.campaigns.length} vs Py ${py.n_campaigns} (greedy-walk split wiggle)`);
  check('waste oxide ±5%',
        Math.abs(totals.total_waste_kg - py.total_waste_kg) / py.total_waste_kg <= 0.05,
        `JS ${(totals.total_waste_kg / 1e6).toFixed(2)} vs Py ${(py.total_waste_kg / 1e6).toFixed(2)} Mt`);
  check('glass mass ±7%',
        Math.abs(totals.total_glass_kg - py.total_glass_kg) / py.total_glass_kg <= 0.07,
        `JS ${(totals.total_glass_kg / 1e6).toFixed(2)} vs Py ${(py.total_glass_kg / 1e6).toFixed(2)} Mt`);
} else {
  console.log('(mission parity fixture missing for', TAG, '— structural checks only)');
}

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed ? 1 : 0);
